"use client";

// Shared data store: demo data (generated by the real CIE engine) or the
// user's own exported files. Zustand keeps it simple — no backend needed.

import { create } from "zustand";
import type { CieReport, CieViewSpec, ConceptTree } from "./cie-types";
import type { ChatChartSpec } from "./chat-chart";
import type { RepoScan } from "./language-profiles";

export type DataSource = "demo" | "custom" | null;

// One bubble in the "Ask CIE" conversation. `chart` is the complementary
// chart the AI attached to its answer (US-020 catalog pick), if any. Failed
// sends carry `technical` (collapsible) and `providerIssue` (offer to open
// the connection settings).
export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
  error?: boolean;
  chart?: ChatChartSpec;
  technical?: string;
  providerIssue?: boolean;
}

interface CieState {
  report: CieReport | null;
  viewspec: CieViewSpec | null;
  concepts: ConceptTree | null;
  source: DataSource;
  label: string;
  loading: boolean;
  loadError: string;
  chat: ChatMessage[];
  chatBusy: boolean;
  jobId: string | null; // active "Connect a repo" job, survives dialog close
  repoScan: RepoScan | null; // language inventory from connect-a-repo flows
  loadDemo: () => Promise<void>;
  setCustom: (
    report: CieReport | null,
    viewspec: CieViewSpec | null,
    concepts: ConceptTree | null,
    label: string,
    repoScan?: RepoScan | null
  ) => void;
  reset: () => void;
  pushChat: (m: ChatMessage) => void;
  setChatBusy: (b: boolean) => void;
  clearChat: () => void;
  setJobId: (id: string | null) => void;
}

export const useCie = create<CieState>((set) => ({
  report: null,
  viewspec: null,
  concepts: null,
  source: null,
  label: "",
  loading: true,
  loadError: "",
  chat: [],
  chatBusy: false,
  jobId: null,
  loadDemo: async () => {
    set({ loading: true, loadError: "" });
    try {
      const [report, viewspec, concepts] = await Promise.all([
        fetch("/data/report.json").then((r) => r.json()),
        fetch("/data/viewspec.json").then((r) => r.json()),
        fetch("/data/concepts.json").then((r) => r.json()),
      ]);
      set({
        report,
        viewspec,
        concepts,
        source: "demo",
        label: "Sample project: a small banking app (4 files)",
        loading: false,
        chat: [],
        chatBusy: false,
        repoScan: null,
      });
    } catch {
      set({ loading: false, loadError: "Could not load the sample data. Please refresh the page." });
    }
  },
  setCustom: (report, viewspec, concepts, label, repoScan) =>
    set({
      report,
      viewspec,
      concepts,
      source: "custom",
      label,
      loading: false,
      loadError: "",
      chat: [],
      chatBusy: false,
      // The scan only exists for connect-a-repo flows; switching to the
      // sample or to uploaded files honestly drops it.
      repoScan: repoScan ?? null,
    }),
  reset: () => {
    void useCie.getState().loadDemo();
  },
  pushChat: (m) => set((s) => ({ chat: [...s.chat, m] })),
  setChatBusy: (b) => set({ chatBusy: b }),
  clearChat: () => set({ chat: [] }),
  setJobId: (id) => set({ jobId: id }),
}));
